+        smallest_outpoint_ser.data(),
+        taproot_pubkey_ptrs.data(), taproot_pubkey_ptrs.size(),
+        plain_pubkey_ptrs.data(), plain_pubkey_ptrs.size()
+    );
+    if (!ret) return std::nullopt;
+    return prevouts_summary;
