+    std::vector<const secp256k1_keypair *> taproot_keypair_ptrs;
+    std::vector<const unsigned char *> plain_key_ptrs;
+    taproot_keypair_ptrs.reserve(taproot_keypairs.size());
+    plain_key_ptrs.reserve(plain_keys.size());
