+    if (type == TxoutType::PUBKEYHASH) {
+        std::vector<std::vector<unsigned char>> stack;
+        ScriptError serror;
+        if (!EvalScript(stack, txin.scriptSig, MANDATORY_SCRIPT_VERIFY_FLAGS, DUMMY_CHECKER, SigVersion::BASE, &serror)) {
